steps.script:
var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.setup(1, {"cp": {"2": 0}})

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
PhaseManager.transition_to_phase(8)
return int(GameState.get_current_phase())

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.frame(8, 40, 1.2)

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.window_id()

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.decider()

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.flag("U_WULFEN_A", "sw11e_eye_of_the_pack")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return (H.codex().apply_wound_bits(0, H.unit("U_WULFEN_A"), {}, false, []) & 16) == 16

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.log_count("Used EYE OF THE PACK")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.shoot("U_WULFEN_A", "U_GRETCHIN_C")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
for b in H.phase().dice_log:
	if typeof(b) == TYPE_DICTIONARY and str(b.get("context", "")) == "to_wound":
		for e in b.get("modifier_ledger", []):
			if str(e.get("source", "")) == "Eye of the Pack":
				return true
return false

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return "U_WULFEN_A" in H.phase().units_that_shot
